-- Script to add courses restrictions, and a list of providers allowed for the resricted courses on das-prd-roatpv2-db
-- Will only add a course for a provider where the provider is authorised for the CourseType 
--
BEGIN TRANSACTION RST;
BEGIN

CREATE TABLE #RestrictedCourses
(
[LarsCode] VARCHAR(10)
);

VALUES (55),
(405),
(555),
(104),
(672),
(237),
(551),
(694),
(269),
(162),
(695),
(420),
(367),
(105),
(532),
(716);

CREATE TABLE #AllowedProviders
(
[Ukprn] BigInt,
[LastDateStarts] DATETIME
);


-- late addition
(10101572,'2026-08-31');


SELECT * FROM #RestrictedCourses;  -- 16
SELECT * FROM #AllowedProviders;   -- 1280

SELECT COUNT(*) "Before: Count of Restricted Courses" 
FROM [dbo].[RestrictedCourse];

MERGE INTO [dbo].[RestrictedCourse] rst
USING #RestrictedCourses upd
ON (rst.[LarsCode] = upd.[LarsCode])
WHEN NOT MATCHED 
THEN INSERT ([LarsCode]) VALUES (upd.[LarsCode])
;

SELECT COUNT(*) "After: Count of Restricted Courses" 
FROM [dbo].[RestrictedCourse];

SELECT COUNT(*) "Before: Count with LastDateStarts" 
FROM [dbo].[ProviderAllowedCourse] 
WHERE [LastDateStarts] IS NOT NULL;

MERGE INTO [dbo].[ProviderAllowedCourse] pac
USING (
	SELECT alp.[Ukprn], rst.[LarsCode], alp.[LastDateStarts]
	FROM [dbo].[ProviderCourse] pc1
	JOIN [dbo].[Provider] pr1 ON pr1.[id] = pc1.[ProviderId]
	JOIN #RestrictedCourses rst on rst.[LarsCode] = pc1.[LarsCode]
	JOIN #AllowedProviders alp on alp.[Ukprn] = pr1.[Ukprn]
) upd
ON (pac.[Ukprn] = upd.[Ukprn] AND pac.[LarsCode] = upd.[LarsCode])
WHEN MATCHED AND ( ISNULL(pac.[LastDateStarts],'1900-01-01') != ISNULL(upd.[LastDateStarts],'1900-01-01') ) THEN 
UPDATE SET pac.[LastDateStarts] = upd.[LastDateStarts],
pac.[UpdatedDate] = GETUTCDATE()
WHEN NOT MATCHED THEN
INSERT ([Ukprn],[LarsCode],[LastDateStarts])
VALUES (upd.[Ukprn],upd.[LarsCode],upd.[LastDateStarts])
;


SELECT COUNT(*) "After: Count with LastDateStarts" 
FROM [dbo].[ProviderAllowedCourse] 
WHERE [LastDateStarts] IS NOT NULL;

DROP TABLE #RestrictedCourses;

DROP TABLE #AllowedProviders;

ROLLBACK TRANSACTION RST;

END;

-- END
